// 原真实行旅之后prepare/apply改道，零距道路仍必须留给原中央释放Action。
#define main private_shop_original_travel_expense_main
#include "private_shop_travel_expense_source_test.cpp"
#undef main
#include "resident/domains/commerce/freight/private_shop_travel_replan_source.hpp"
namespace {
// 地形原地图配置，不为改道另造假的付款/计划来源。
void replan_map(Fixture& f){terrain::TerrainMap map;map.id="map";map.width=40;map.height=20;map.cell_size=20;map.cells.resize(2);map.budgets={{terrain::Mode::foot,10},{terrain::Mode::army,10},{terrain::Mode::boat,10}};map.money_per_tick=7;map.fatigue_per_tick=2;require(terrain::validate_map(map).ok,"actual replan map");f.catalog.world_map_id=map.id;f.catalog.maps.insert(map.id,map);f.catalog.settlements.find("A")->map_xy={10,10};f.catalog.settlements.find("B")->map_xy={30,10};}
// 实付一个原step后才真正返程；新plan不能清掉已经付过的款或覆盖旧plan。
void actual_replan(bool terrain_mode){Fixture f;if(terrain_mode)replan_map(f);const auto id=f.begin("carrier","B");require(step_travel(f.common,f.travel,f.catalog,f.services,id).ok,"actual paid step before return");auto op=prepare_travel_control(f.common,f.travel,f.catalog,f.services,"carrier",ReturnTravelCommand{});require(op.ok,"actual original return quote");require(f.common.begin_resource_execution_capture().ok,"actual replan capture");auto b=capture_private_shop_travel_replan_boundary(f.common,f.travel,f.catalog,op.value);require(b.ok,"actual original replan boundary");const auto next=f.common.state().next_instance_id;const auto plans=f.travel.journey_facts.size();std::optional<TravelControlDraft> draft;require(apply_travel_control(f.common,f.travel,f.catalog,op.value,&draft).ok&&draft.has_value(),"actual original replan applied");require(read_private_shop_travel_replan(f.common,f.travel,f.catalog,b.value,*draft).ok,"match exact original replan");check(f.funds("carrier")==93&&f.common.resource_execution_drafts().empty(),"replan neither prepays nor refunds");check(f.common.state().next_instance_id==next+(terrain_mode?1:0)&&f.travel.journey_facts.size()==plans+(terrain_mode?1:0),"only terrain allocates its one actual source head");
 auto bad=*draft;bad.original_control.quote->cost++;check(!read_private_shop_travel_replan(f.common,f.travel,f.catalog,b.value,bad).ok,"original quote cannot be replaced");bad=*draft;bad.original_control.command=PauseTravelCommand{};check(!read_private_shop_travel_replan(f.common,f.travel,f.catalog,b.value,bad).ok,"no-fee pause cannot become replan source");bad=*draft;bad.before.action.start_tick++;check(!read_private_shop_travel_replan(f.common,f.travel,f.catalog,b.value,bad).ok,"original action start retained");if(terrain_mode){const auto old=draft->before.terrain_plan->id;f.travel.journey_facts.erase(old);check(!read_private_shop_travel_replan(f.common,f.travel,f.catalog,b.value,*draft).ok,"old terrain source cannot disappear on replan");}else{f.travel.road_actions.find(id)->payer_wallet_id="wallet.other";check(!read_private_shop_travel_replan(f.common,f.travel,f.catalog,b.value,*draft).ok,"road replan cannot replace original payer");}
 require(f.common.finish_resource_execution_capture().ok,"end original replan capture");require(f.common.begin_resource_execution_capture().ok,"restart original Common");check(!read_private_shop_travel_replan(f.common,f.travel,f.catalog,b.value,*draft).ok,"old replan boundary cannot cross restart");}
// 此真实零距返程只安装起点位置，读取成功仍不表示原Action已经释放。
void zero_distance_replan(){Fixture f;auto id=f.begin("carrier","B");auto op=prepare_travel_control(f.common,f.travel,f.catalog,f.services,"carrier",ReturnTravelCommand{});require(op.ok&&op.value.quote&&op.value.quote->duration==0,"actual zero-distance road return");require(f.common.begin_resource_execution_capture().ok,"zero-distance original capture");auto b=capture_private_shop_travel_replan_boundary(f.common,f.travel,f.catalog,op.value);require(b.ok,"zero-distance original boundary");std::optional<TravelControlDraft> d;require(apply_travel_control(f.common,f.travel,f.catalog,op.value,&d).ok&&d.has_value(),"actual zero-distance writer");require(read_private_shop_travel_replan(f.common,f.travel,f.catalog,b.value,*d).ok,"zero-distance source matched");check(f.common.action(id)&&std::holds_alternative<SettlementLocation>(f.common.actor("carrier")->location)&&f.funds("carrier")==100,"original active Action retained with origin location and no fee");}
}
int main(){try{actual_replan(false);actual_replan(true);zero_distance_replan();}catch(const std::exception& e){check(false,e.what());}std::cout<<"PRIVATE_SHOP_REPLAN_CHECKS="<<checks<<" FAILURES="<<failures<<'\n';return failures?1:0;}
